ROWS = []
for i in range(1, 13):
    ROWS.append({
        "id": i,
        "dept": "d" + str((i % 3) + 1),
        "salary": 40 + i * 5,
        "city": "bj" if i % 2 == 1 else "sh",
    })

EXEC_COUNT = 0


class DF:
    def __init__(self, source, ops=()):
        self.source = source
        self.ops = list(ops)

    def _derive(self, op):
        global EXEC_COUNT
        print("  [登记] " + op + "   此时 EXEC_COUNT=" + str(EXEC_COUNT))
        return DF(self.source, self.ops + [op])

    def filter(self, pred):
        return self._derive("Filter(" + pred + ")")

    def select(self, cols):
        return self._derive("Project(" + ",".join(cols) + ")")

    def groupBy(self, key):
        return self._derive("Aggregate(groupBy=" + key + ")")

    def plan(self):
        return "Scan(" + self.source + ") -> " + " -> ".join(self.ops)

    def collect(self):
        global EXEC_COUNT
        EXEC_COUNT += 1
        return [r for r in ROWS if r["salary"] > 60]

    def count(self):
        global EXEC_COUNT
        EXEC_COUNT += 1
        return len(ROWS)


